(x, y, t) => {
  const w1x = Math.sin(y*0.018+t*0.3)*12+Math.cos((x+y)*0.012-t*0.2)*8;
  const w1y = Math.cos(x*0.016-t*0.25)*12+Math.sin((x-y)*0.014+t*0.35)*8;
  const x1=x+w1x, y1=y+w1y;
  const w2x = Math.sin(y1*0.025-t*0.4)*6+Math.cos(x1*0.02+t*0.15)*5;
  const w2y = Math.cos(x1*0.022+t*0.35)*6+Math.sin(y1*0.018-t*0.2)*5;
  const x2=x1+w2x, y2=y1+w2y;
  const src=[
    [160+Math.sin(t*0.5)*100,80+Math.cos(t*0.35)*50,0.08,2.0,0.9],
    [320+Math.cos(t*0.45)*100,160+Math.sin(t*0.6)*50,0.1,1.7,1.1],
    [240+Math.sin(t*0.25+2)*140,120+Math.cos(t*0.4+1)*90,0.06,2.3,0.8],
    [120+Math.cos(t*0.7+1)*80,180+Math.sin(t*0.5+3)*60,0.12,1.5,1.2],
    [360+Math.sin(t*0.35+4)*90,60+Math.cos(t*0.8+2)*70,0.07,2.6,0.7],
    [240+Math.cos(t*0.3+5)*120,200+Math.sin(t*0.5)*80,0.09,1.9,1.0],
    [80+Math.sin(t*0.55+3)*70,40+Math.cos(t*0.65+4)*40,0.11,2.1,0.85],
    [400+Math.cos(t*0.4+2)*60,200+Math.sin(t*0.75)*50,0.085,1.8,1.15]
  ];
  let act=0,inh=0,feed=0;
  for(const[sX,sY,f,sp,amp]of src){
    const d=Math.sqrt((x2-sX)**2+(y2-sY)**2);
    act+=Math.sin(d*f-t*sp)*amp;
    inh+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*amp;
    feed+=Math.sin(d*f*1.3-t*sp*0.8+2.8)*amp*0.5;
  }
  act/=8;inh/=8;feed/=8;
  const bg1=(Math.sin(x2*0.04+y2*0.025+t*0.8)+Math.sin(x2*0.03-y2*0.04+t*1.1))/2;
  const bg2=Math.sin((x2+y2)*0.12+t*2.5)*0.2+Math.sin((x2-y2)*0.1-t*2)*0.2;
  const bg3=Math.sin(x2*0.07+t*0.5)*Math.cos(y2*0.06-t*0.4)*0.3;
  const bg=bg1+bg2+bg3;
  const cx=240,cy=120;
  const dist=Math.sqrt((x2-cx)**2+(y2-cy)**2);
  const ang=Math.atan2(y2-cy,x2-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.06-ang*2+t*0.8))*0.27;
  const vx=Math.sin(x2*0.15)*Math.cos(y2*0.12+t*0.3);
  const vy=Math.cos(x2*0.13-t*0.2)*Math.sin(y2*0.16);
  const cell=Math.tanh((vx*vy+Math.sin((x2+y2)*0.1+t)*0.5)*1.5)*0.3;
  const rd=act-inh*0.7+feed*0.4+bg*0.25+spiral;
  const reaction=Math.tanh(rd*2.0);
  const rd2=Math.sin(act*inh+bg*2)*0.3+Math.cos(feed*3-spiral)*0.2;
  const reaction2=Math.tanh(rd2*1.5)*0.15;
  const blend=reaction*0.8+cell*0.15+reaction2*0.05;
  const v=blend*0.5+0.5;
  const pal=[
    [6,12,42],[12,45,85],[15,90,120],[25,155,145],
    [80,190,140],[190,200,100],[230,175,60],[215,110,55],
    [175,60,60],[120,30,55],[65,15,55],[20,10,48],[6,12,42]
  ];
  const idx=v*(pal.length-1);
  const i=Math.min(idx|0,pal.length-2);
  const f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.65?1.2:1.0;
  const glow=Math.max(0,reaction-0.3)*0.3;
  const r=(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40;
  const g=(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*25;
  const b=(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*15;
  return[Math.min(255,r)|0,Math.min(255,g)|0,Math.min(255,b)|0];
}
